<?php require 'includes/db.php'; require 'includes/header.php'; $products=db()->query('SELECT * FROM products ORDER BY category,name')->fetchAll(); ?>
<h1>Shop</h1><div class="grid products"><?php foreach($products as $p): ?><article class="card"><span class="tag"><?=e($p['category'])?></span><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><strong>₹<?=number_format($p['price'],2)?></strong><p class="muted">Stock: <?=(int)$p['stock']?></p><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1"><button class="btn" name="add">Add to Cart</button></form></article><?php endforeach; ?></div>
<?php require 'includes/footer.php'; ?>